    composerContext,
    composerLead,
    composerActions,
    composerTrailingActions,
    messageMeta,
    followUps,
  } = useAssistantSettings()
  const hasCommands = Boolean(commands?.length)
  const hasContext = composerContext != null
  const hasActions = showModels || composerActions != null
  const components = React.useMemo(
