import * as React from "react"
import {
  unstable_useSlashCommandAdapter,
  useAui,
  type AssistantClient,
  type Unstable_TriggerItem,
  type Unstable_TriggerMatcher,
} from "@assistant-ui/react"

import { ComposerTriggerPopover } from "@/components/assistant-ui/elements/composer-trigger-popover.aui"
import { Icon } from "@/components/forge/icon"
import type { IconProp } from "@/components/forge/icons"

import { useAssistantSettings } from "./assistant-context"

/**
 * A `/` command in the composer. What picking it does depends on its fields:
 *
 * - `execute`: runs in the app (start a conversation, open a sheet…); the
 *   typed `/command` is removed.
 * - `prompt`: fills the composer with the prompt, and sends it with `send`.
 * - neither: leaves `/id ` in the composer for the user to add arguments to,
 *   and the agent receives the command as text (handle it in its
 *   instructions).
 */
export type AssistantCommand = {
  /** Typed after the slash: `deploy` is `/deploy`. */
  id: string
  description?: string
  /** A Forge icon name or a Hugeicons glyph. */
  icon?: IconProp
  prompt?: string
  /** With `prompt`: send it straight away instead of leaving it to edit. */
  send?: boolean
  execute?: (aui: AssistantClient) => void
}

// Commands only open from a `/` at the very start of the message, so a path
// or a fraction later in the text never pops the menu.
const atStartOfMessage: Unstable_TriggerMatcher = (text, char, cursor) => {
  if (!text.startsWith(char)) return null
  const query = text.slice(char.length, cursor)
  return /\s/u.test(query) ? null : { query, offset: 0, endOffset: cursor }
}

function runCommand(command: AssistantCommand, aui: AssistantClient) {
  // The popover has removed the typed `/query` by now.
  const rest = aui.composer.getState().text.trimStart()
  if (command.execute) {
    command.execute(aui)
  } else if (command.prompt !== undefined) {
    aui.composer.setText(rest ? `${command.prompt} ${rest}` : command.prompt)
    if (command.send) aui.composer.send()
  } else {
    aui.composer.setText(`/${command.id} ${rest}`)
  }
}

// assistant-ui also matches descriptions; commands whose name starts with the
// query come first, then other name matches, then description matches.
const rank = (item: Unstable_TriggerItem, query: string) => {
  const id = item.id.toLowerCase()
  if (id.startsWith(query)) return 0
  return id.includes(query) ? 1 : 2
}

type TriggerAdapter = ReturnType<
  typeof unstable_useSlashCommandAdapter
>["adapter"]

function byName(adapter: TriggerAdapter): TriggerAdapter {
  return {
    ...adapter,
    search: (query) => {
      const lower = query.toLowerCase()
      return [...(adapter.search?.(query) ?? [])].sort(
        (a, b) => rank(a, lower) - rank(b, lower)
      )
    },
  }
}

type GlyphComponent = React.FC<{ className?: string }>

// One stable component per icon, so the popover's icon map never remounts.
const glyphs = new Map<IconProp, GlyphComponent>()
function glyphFor(icon: IconProp): GlyphComponent {
  let glyph = glyphs.get(icon)
  if (!glyph) {
    glyph = ({ className }) => <Icon icon={icon} className={className} />
    glyphs.set(icon, glyph)
  }
  return glyph
}

/**
 * The `/` command menu above the composer, for `AssistantScreen`'s
 * `commands`. Arrow keys move, Enter or Tab picks, Escape closes.
 */
function AssistantCommandMenu() {
  const { commands = [] } = useAssistantSettings()
  const aui = useAui()
  const slash = unstable_useSlashCommandAdapter({
    commands: commands.map((command) => ({
      id: command.id,
      description: command.description,
      icon: command.id,
      // The popover removes the typed `/query` as it calls this, and the
      // composer state reflects that from the next task.
      execute: () => setTimeout(() => runCommand(command, aui)),
    })),
    removeOnExecute: true,
  })
  const adapter = React.useMemo(() => byName(slash.adapter), [slash.adapter])
  const iconMap = React.useMemo(
    () =>
      Object.fromEntries(
        commands.flatMap((command) =>
          command.icon ? [[command.id, glyphFor(command.icon)]] : []
        )
      ),
    [commands]
  )

  return (
    <ComposerTriggerPopover
      char="/"
      matcher={atStartOfMessage}
      adapter={adapter}
      action={slash.action}
      iconMap={iconMap}
      emptyItemsLabel="No matching commands"
    />
  )
}

export { AssistantCommandMenu }

import type { IconProp } from "@/components/forge/icons"

/** A model the agent can run on, picked from the composer's model section. */
export type AssistantModel = {
  /** Sent to the agent, e.g. "gemini-2.5-pro". */
  id: string
  name: string
  description?: string
  /**
   * Models with the same group are listed together under it, e.g. their
   * provider ("OpenAI"), in the order the groups first appear.
   */
  group?: string
  /** Shown before its name, e.g. its maker's mark. */
  icon?: IconProp
  /**
   * The ids of the thinking levels it offers, e.g. `["off"]` for a model
   * that doesn't reason. Default: every level of the model section.
   */
  thinkingLevels?: string[]
}

/** How long the model thinks before it answers. */
export type ThinkingLevel = {
  /** Sent to the agent, e.g. "high". */
  id: string
  label: string
  description?: string
}

export const defaultThinkingLevels: ThinkingLevel[] = [
  { id: "off", label: "Off", description: "Answer straight away" },
  { id: "low", label: "Low", description: "A quick plan first" },
  { id: "medium", label: "Medium", description: "Balanced for most work" },
  {
    id: "high",
    label: "High",
    description: "Longest reasoning, for hard problems",
  },
]

/**
 * Every level a model provider configuration knows (model_provider.yaml, as
 * the coding agent and the Forge agent read it), from least to most thinking.
 * Pass it as `thinkingLevels` with models that say which they offer.
 */
export const extendedThinkingLevels: ThinkingLevel[] = [
  { id: "off", label: "Off", description: "Answer straight away" },
  { id: "minimal", label: "Minimal", description: "The briefest look first" },
  { id: "low", label: "Low", description: "A quick plan first" },
  { id: "medium", label: "Medium", description: "Balanced for most work" },
  {
    id: "high",
    label: "High",
    description: "Long reasoning, for hard problems",
  },
  {
    id: "xhigh",
    label: "Extra high",
    description: "Longest reasoning, for the hardest problems",
  },
]

/**
 * The level a model runs at when `id` is chosen: that one if it's among
 * `levels`, else the nearest above it in `order`, else the nearest below,
 * else the first. The same rule the server applies.
 */
export function nearestThinkingLevel(
  levels: ThinkingLevel[],
  order: ThinkingLevel[],
  id: string
): string | undefined {
  if (levels.some((level) => level.id === id)) return id
  const offered = new Set(levels.map((level) => level.id))
  const index = order.findIndex((level) => level.id === id)
  if (index >= 0) {
    const above = order.slice(index + 1).find((level) => offered.has(level.id))
    if (above) return above.id
    const below = order
      .slice(0, index)
      .reverse()
      .find((level) => offered.has(level.id))
    if (below) return below.id
  }
  return levels[0]?.id
}

/** What the model section has selected, sent with every run. */
export type ModelSelection = {
  model: string | undefined
  thinkingLevel: string
}

/**
 * The model section's choices and selection, from `useAdkAssistant`. Pass it
 * to `AssistantScreen` with `showModels`.
 */
export type ModelSettings = ModelSelection & {
  models: AssistantModel[]
  /** The selected model's levels. */
  thinkingLevels: ThinkingLevel[]
  setModel: (id: string) => void
  setThinkingLevel: (id: string) => void
  /**
   * Called by the model section while it's mounted: the selection is only
   * sent while someone can see it. Returns the cleanup.
   */
  show: () => () => void
}

/** The default ADK state delta: `model` and `thinking_level` session keys. */
export const defaultModelStateDelta = ({
  model,
  thinkingLevel,
}: ModelSelection): Record<string, unknown> => ({
  ...(model && { model }),
  thinking_level: thinkingLevel,
})

/*
 * Citation markers in an agent's answer: "[S3]", or "[S1, S3]", each naming a
 * passage by the ref its tool result gave it (see sources.tsx).
 */

/** "[S3]", or several at once: "[S1, S3]". */
const MARKER = /\[([A-Z]{1,3}\d{1,4}(?:\s*,\s*[A-Z]{1,3}\d{1,4})*)\]/g
export const REF_HREF = "#source-"

const refsIn = (marker: string) => marker.split(",").map((ref) => ref.trim())

/** The refs a text cites, first citation first. */
export function citedRefs(text: string): string[] {
  const refs = new Set<string>()
  for (const match of text.matchAll(MARKER)) {
    for (const ref of refsIn(match[1] ?? "")) refs.add(ref)
  }
  return [...refs]
}

type MdNode = {
  type: string
  value?: string
  url?: string
  children?: MdNode[]
}

/**
 * A remark plugin: each "[S3]" in the text becomes a link to `#source-S3`,
 * which `SourceAnchor` draws as a citation. Code and links are left alone.
 */
export function remarkSourceRefs() {
  return (tree: MdNode) => linkRefs(tree)
}

function linkRefs(node: MdNode): void {
  if (!node.children || node.type === "link" || node.type === "linkReference")
    return
  const children: MdNode[] = []
  for (const child of node.children) {
    const text = child.type === "text" ? (child.value ?? "") : ""
    let last = 0
    for (const match of text.matchAll(MARKER)) {
      const start = match.index ?? 0
      if (start > last) {
        // The space before a citation doesn't break: it stays with its word.
        const before = text.slice(last, start).replace(/ $/, "\u00a0")
        children.push({ type: "text", value: before })
      }
      for (const ref of refsIn(match[1] ?? "")) {
        children.push({
          type: "link",
          url: `${REF_HREF}${ref}`,
          children: [{ type: "text", value: `[${ref}]` }],
        })
      }
      last = start + match[0].length
    }
    if (last === 0) {
      linkRefs(child)
      children.push(child)
    } else if (last < text.length) {
      children.push({ type: "text", value: text.slice(last) })
    }
  }
  node.children = children
}

import * as React from "react"
import { useAuiState, type ThreadMessage } from "@assistant-ui/react"
import { cn } from "cn"

import { MarkdownText } from "@/components/assistant-ui/elements/markdown-text"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { Icon } from "@/components/forge/icon"

import { useAssistantSettings } from "./assistant-context"
import { REF_HREF, citedRefs, remarkSourceRefs } from "./source-refs"

/*
 * Cited sources. An agent's tools return passages that each carry a ref
 * ("S3"); the agent cites them inline as "[S3]". The tool results stream with
 * the answer, in the same message, so the console resolves every ref from
 * them: no second channel, and the sources come back with the conversation.
 */

/** A document an answer can cite; its passages are listed together. */
export type AssistantSourceDocument = {
  /** Identifies the document. */
  key: string
  /** Its name, e.g. the filename. */
  title: string
  /** Where it's from, e.g. the team. */
  subtitle?: string
  /** Opens the document, in a new tab. */
  href?: string
}

/** A passage a tool returned, which the agent cites by `ref`. */
export type AssistantSource = {
  /** What the agent writes in brackets, e.g. "S3". */
  ref: string
  document: AssistantSourceDocument
  /** Where in the document: section, page, sheet. */
  location?: string
  /** The passage, shortened. */
  excerpt?: string
}

/** How answers cite what the agent's tools found. */
export type AssistantSourcesConfig = {
  /** The sources in a finished tool call's result; [] for other tools. */
  fromToolCall: (toolName: string, result: unknown) => AssistantSource[]
}

/* -------------------------------------------------------------------------- */
/* Where the refs point                                                       */
/* -------------------------------------------------------------------------- */

type Cached = { config: AssistantSourcesConfig; sources: AssistantSource[] }
// A message's sources, read once per version of it.
const perMessage = new WeakMap<ThreadMessage, Cached>()

function sourcesOf(
  message: ThreadMessage,
  config: AssistantSourcesConfig
): AssistantSource[] {
  const cached = perMessage.get(message)
  if (cached?.config === config) return cached.sources
  const sources: AssistantSource[] = []
  if (message.role === "assistant") {
    for (const part of message.content) {
      if (part.type !== "tool-call" || part.result === undefined) continue
      if (part.isError) continue
      try {
        sources.push(...config.fromToolCall(part.toolName, part.result))
      } catch {
        // A result the config can't read cites nothing.
      }
    }
  }
  perMessage.set(message, { config, sources })
  return sources
}

/** Every source the conversation's tools returned, by ref. */
function useThreadSources() {
  const config = useAssistantSettings().sources
  const messages = useAuiState((s) => s.thread.messages)
  return React.useMemo(() => {
    const byRef = new Map<string, AssistantSource>()
    if (config) {
      for (const message of messages) {
        for (const source of sourcesOf(message, config)) {
          byRef.set(source.ref, source)
        }
      }
    }
    return byRef
  }, [messages, config])
}

/** The refs this message cites, in order: [S7, S2] numbers S7 as 1. */
function useMessageCitations() {
  const text = useAuiState((s) =>
    s.message.content
      .map((part) => (part.type === "text" ? part.text : ""))
      .join("\n")
  )
  return React.useMemo(() => citedRefs(text), [text])
}

/* -------------------------------------------------------------------------- */
/* Citations in the text                                                      */
/* -------------------------------------------------------------------------- */

const chip =
  "inline-flex h-4 min-w-4 shrink-0 items-center justify-center rounded-(--radius-chip) bg-muted px-1 font-sans text-3xs leading-none font-medium text-muted-foreground tabular-nums"

/**
 * A citation: its number in this answer, opening the passage behind it on
 * hover or press. A ref no tool returned stays the text the agent wrote.
 */
function SourceRef({ id }: { id: string }) {
  const byRef = useThreadSources()
  const cited = useMessageCitations()
  const source = byRef.get(id)
  const number = cited.indexOf(id) + 1
  if (!source || number === 0) return <>{`[${id}]`}</>
  return (
    <Popover>
      {/* A span, not a button: an inline box keeps the no-break space
          before it, so a citation never wraps away from its word. */}
      <PopoverTrigger
        openOnHover
        delay={150}
        nativeButton={false}
        render={<span />}
        aria-label={`Source ${number}: ${source.document.title}`}
        className="relative -top-px ms-0.5 cursor-pointer rounded-(--radius-chip) bg-muted px-1 py-px font-sans text-3xs font-medium whitespace-nowrap text-muted-foreground tabular-nums transition-colors duration-100 hover:bg-accent hover:text-foreground data-popup-open:bg-accent data-popup-open:text-foreground"
      >
        {number}
      </PopoverTrigger>
      <PopoverContent side="top" align="start" className="w-80 gap-2">
        <SourceCard source={source} number={number} />
      </PopoverContent>
    </Popover>
  )
}

function SourceCard({
  source,
  number,
}: {
  source: AssistantSource
  number: number
}) {
  const { document } = source
  const where = [document.subtitle, source.location].filter(Boolean).join(" · ")
  return (
    <>
      <div className="flex min-w-0 items-start gap-2">
        <span className={cn(chip, "mt-px")}>{number}</span>
        <div className="grid min-w-0 gap-0.5">
          <p className="truncate font-medium text-foreground">
            {document.title}
          </p>
          {where && <p className="text-muted-foreground">{where}</p>}
        </div>
      </div>
      {source.excerpt && (
        <p className="line-clamp-4 text-muted-foreground">{source.excerpt}</p>
      )}
      {document.href && (
        <a
          href={document.href}
          target="_blank"
          rel="noreferrer"
          className="inline-flex items-center gap-1 self-start font-medium text-foreground underline-offset-2 hover:underline"
        >
          Open document
          <Icon icon="external" size={13} />
        </a>
      )}
    </>
  )
}

/** Markdown links: citations from `remarkSourceRefs`, else a plain link. */
function SourceAnchor({
  href,
  className,
  children,
  ...props
}: React.ComponentProps<"a">) {
  if (href?.startsWith(REF_HREF))
    return <SourceRef id={href.slice(REF_HREF.length)} />
  return (
    <a
      href={href}
      className={cn(
        "aui-md-a text-primary underline underline-offset-2 hover:text-primary/80",
        className
      )}
      {...props}
    >
      {children}
    </a>
  )
}

const sourceComponents = { a: SourceAnchor }
const sourcePlugins = [remarkSourceRefs]

/** An answer's text, its "[S3]" citations drawn as numbered sources. */
export function SourcedMarkdownText() {
  const config = useAssistantSettings().sources
  if (!config) return <MarkdownText />
  return (
    <MarkdownText components={sourceComponents} remarkPlugins={sourcePlugins} />
  )
}

/* -------------------------------------------------------------------------- */
/* Sources under the answer                                                   */
/* -------------------------------------------------------------------------- */

type DocumentGroup = {
  document: AssistantSourceDocument
  sources: AssistantSource[]
}

function groupByDocument(sources: AssistantSource[]): DocumentGroup[] {
  const groups = new Map<string, DocumentGroup>()
  for (const source of sources) {
    const group = groups.get(source.document.key)
    if (group) group.sources.push(source)
    else
      groups.set(source.document.key, {
        document: source.document,
        sources: [source],
      })
  }
  return [...groups.values()]
}

function DocumentTitle({ document }: { document: AssistantSourceDocument }) {
  return document.href ? (
    <a
      href={document.href}
      target="_blank"
      rel="noreferrer"
      className="truncate font-medium text-foreground underline-offset-2 hover:underline"
    >
      {document.title}
    </a>
  ) : (
    <span className="truncate font-medium text-foreground">
      {document.title}
    </span>
  )
}

function DocumentRow({
  group,
  cited,
}: {
  group: DocumentGroup
  cited: boolean
}) {
  const locations = [
    ...new Set(group.sources.map((s) => s.location).filter(Boolean)),
  ]
  return (
    <li className="flex min-w-0 items-start gap-2 text-xs">
      {cited ? (
        <span className="mt-px flex shrink-0 gap-0.5">
          {group.sources.map((source) => (
            <SourceRef key={source.ref} id={source.ref} />
          ))}
        </span>
      ) : (
        <Icon
          icon="file"
          size={14}
          className="mt-px shrink-0 text-muted-foreground"
        />
      )}
      <div className="grid min-w-0 flex-1 gap-px">
        <div className="flex min-w-0 items-baseline gap-2">
          <DocumentTitle document={group.document} />
          {group.document.subtitle && (
            <span className="ms-auto shrink-0 text-2xs text-subtle">
              {group.document.subtitle}
            </span>
          )}
        </div>
        {locations.length > 0 && (
          <span className="truncate text-2xs text-muted-foreground">
            {locations.join(" · ")}
          </span>
        )}
      </div>
    </li>
  )
}

const plural = (count: number, one: string) =>
  `${count} ${one}${count === 1 ? "" : "s"}`

/**
 * The documents under an answer: the ones it cites, numbered as in the text,
 * then the others its searches found. Shown once the answer is complete.
 */
export function MessageSources() {
  const config = useAssistantSettings().sources
  const message = useAuiState((s) => s.message)
  const byRef = useThreadSources()
  const cited = useMessageCitations()
  if (!config || message.role !== "assistant") return null
  if (message.status?.type === "running") return null

  const citedSources = cited.flatMap((ref) => byRef.get(ref) ?? [])
  const citedGroups = groupByDocument(citedSources)
  const citedKeys = new Set(citedGroups.map((g) => g.document.key))
  const searched = groupByDocument(sourcesOf(message, config)).filter(
    (g) => !citedKeys.has(g.document.key)
  )
  if (!citedGroups.length && !searched.length) return null

  return (
    <section
      aria-label="Sources"
      data-slot="assistant-message-sources"
      className="mt-3 grid gap-1.5 border-t border-border pt-2.5"
    >
      {citedGroups.length > 0 && (
        <>
          <p className="text-2xs font-medium text-muted-foreground">Sources</p>
          <ul className="grid gap-1.5">
            {citedGroups.map((group) => (
              <DocumentRow key={group.document.key} group={group} cited />
            ))}
          </ul>
        </>
      )}
      {searched.length > 0 && (
        <Collapsible>
          <CollapsibleTrigger className="group/searched inline-flex items-center gap-1 text-2xs font-medium text-muted-foreground hover:text-foreground">
            {citedGroups.length ? "Also searched" : "Searched"}{" "}
            {plural(searched.length, "document")}
            <Icon
              icon="down"
              size={13}
              className="transition-transform duration-150 group-data-panel-open/searched:rotate-180"
            />
          </CollapsibleTrigger>
          <CollapsibleContent>
            <ul className="mt-1.5 grid gap-1.5">
              {searched.map((group) => (
                <DocumentRow
                  key={group.document.key}
                  group={group}
                  cited={false}
                />
              ))}
            </ul>
          </CollapsibleContent>
        </Collapsible>
      )}
    </section>
  )
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import {
  WebSpeechDictationAdapter,
  type AssistantRuntime,
  type DictationAdapter,
  type FeedbackAdapter,
  type ThreadMessage,
} from "@assistant-ui/react"
import {
  createAdkSessionAdapter,
  createAdkStream,
  useAdkRuntime,
  type AdkEvent,
  type AdkStreamCallback,
  type UseAdkRuntimeOptions,
} from "@assistant-ui/react-google-adk"

import {
  defaultModelStateDelta,
  defaultThinkingLevels,
  nearestThinkingLevel,
  type AssistantModel,
  type ModelSelection,
  type ModelSettings,
  type ThinkingLevel,
} from "./model-settings"

type Headers = Record<string, string> | (() => Record<string, string>)

/** Fetch, list and delete a session's artifacts (direct ADK connections). */
export type AdkArtifactsApi = ReturnType<
  typeof createAdkSessionAdapter
>["artifacts"]

export type UseAdkAssistantOptions = Omit<
  UseAdkRuntimeOptions,
  "stream" | "sessionAdapter"
> & {
  /**
   * Proxy mode: your own API route, e.g. one built with `createAdkApiRoute`
   * from `@assistant-ui/react-google-adk/server`.
   */
  api?: string
  /**
   * Direct mode: an ADK server (`adk api_server`, `adk web`). Its sessions
   * become the thread list, and artifacts can be fetched.
   */
  adk?: { url: string; appName: string; userId: string }
  /** Sent with every request; a function is read per request. */
  headers?: Headers
  /**
   * ADK session state sent with every run, read as it's sent: e.g. what the
   * person is looking at, `() => ({ page_context: currentPage() })`. The
   * model section's keys win over the same keys here.
   */
  runState?: () => Record<string, unknown> | undefined
  /** A custom transport instead of `api` / `adk` (tests, mocks). */
  stream?: AdkStreamCallback
  /**
   * Voice input for the composer's mic button; the words appear in the input
   * as they're recognised. Default: the browser's own speech recognition
   * (Web Speech API), where the browser has it. `false` turns it off; any
   * assistant-ui `DictationAdapter` (e.g. a server speech-to-text) replaces it.
   */
  dictation?: boolean | DictationAdapter
  /**
   * Shows thumbs up / down on the agent's replies and receives each rating,
   * e.g. to store it next to the ADK session. Without it the buttons are
   * hidden.
   */
  onFeedback?: (feedback: AssistantFeedback) => void | Promise<void>
  /**
   * Models to choose from in the composer's model section (`showModels`).
   * They may arrive after the first render, e.g. from the agent server.
   */
  models?: AssistantModel[]
  /** Default: the first model. */
  defaultModel?: string
  /**
   * Thinking levels for the model section, from least to most thinking; a
   * model's own `thinkingLevels` narrows them. Default: off, low, medium,
   * high.
   */
  thinkingLevels?: ThinkingLevel[]
  /**
   * Default: "medium" when it's a level, otherwise the first. A model that
   * doesn't offer it gets the nearest level it does.
   */
  defaultThinkingLevel?: string
  /**
   * Turns the model section's selection into the ADK `stateDelta` sent with
   * each run. Default: `{ model, thinking_level }`.
   */
  modelStateDelta?: (selection: ModelSelection) => Record<string, unknown>
}

/**
 * The assistant-ui runtime for a Google ADK agent. Pass the result to
 * `AssistantScreen`: `runtime`, `artifacts` and the model section's
 * `modelSettings`.
 */
export function useAdkAssistant({
  api,
  adk,
  headers,
  runState,
  stream,
  dictation = true,
  onFeedback,
  models = noModels,
  defaultModel,
  thinkingLevels = defaultThinkingLevels,
  defaultThinkingLevel,
  modelStateDelta = defaultModelStateDelta,
  ...options
}: UseAdkAssistantOptions) {
  // Headers may change (a refreshed token) without rebuilding the transport:
  // the getter is created once and reads the latest headers per request.
  const headersRef = useRef(headers)
  useEffect(() => {
    headersRef.current = headers
  })
  const [getHeaders] = useState(() => () => {
    const current = headersRef.current
    return typeof current === "function" ? current() : (current ?? {})
  })

  const { url, appName, userId } = adk ?? {}
  const connection = useMemo(() => {
    if (stream) return { stream }
    if (url && appName && userId) {
      const session = createAdkSessionAdapter({
        apiUrl: url,
        appName,
        userId,
        headers: getHeaders,
      })
      return {
        stream: createAdkStream({
          api: url,
          appName,
          userId,
          headers: getHeaders,
        }),
        sessionAdapter: session.adapter,
        load: session.load,
        artifacts: session.artifacts,
      }
    }
    if (api) return { stream: createAdkStream({ api, headers: getHeaders }) }
    throw new Error(
      "useAdkAssistant needs `api` (your route), `adk` (an ADK server) or `stream`."
    )
  }, [stream, url, appName, userId, api, getHeaders])

  const { settings: modelSettings, shown: modelsShown } = useModelSettings({
    models,
    defaultModel,
    thinkingLevels,
    defaultThinkingLevel,
  })

  // Runs carry `runState` and, while it's shown, the model section's
  // selection as ADK state.
  const selectionRef = useRef<ModelSelection | undefined>(undefined)
  const toStateDeltaRef = useRef(modelStateDelta)
  const runStateRef = useRef(runState)
  useEffect(() => {
    const { model, thinkingLevel } = modelSettings
    selectionRef.current = modelsShown ? { model, thinkingLevel } : undefined
    toStateDeltaRef.current = modelStateDelta
    runStateRef.current = runState
  })
  const send = useCallback<AdkStreamCallback>(
    async function* (messages, config) {
      const selection = selectionRef.current
      try {
        const state = runStateRef.current?.()
        yield* await connection.stream(
          messages,
          selection || state
            ? {
                ...config,
                stateDelta: {
                  ...config.stateDelta,
                  ...state,
                  ...(selection && toStateDeltaRef.current(selection)),
                },
              }
            : config
        )
      } catch (error) {
        // Stop aborts the run; that isn't a failure to show.
        if (config.abortSignal.aborted) throw error
        // The SDK would drop the error and leave the thread silent; as an ADK
        // error event it shows as a failed reply, like the agent's own errors.
        yield requestFailed(error)
      }
    },
    [connection]
  )

  // Created once: the browser adapter starts a fresh recognition per session.
  const [browserDictation] = useState(() =>
    WebSpeechDictationAdapter.isSupported()
      ? new WebSpeechDictationAdapter()
      : undefined
  )
  const dictationAdapter =
    dictation === true ? browserDictation : dictation || undefined
  // Created once: reads the latest handler and session for each rating.
  const onFeedbackRef = useRef(onFeedback)
  const runtimeRef = useRef<AssistantRuntime | null>(null)
  // Only direct connections know ADK session ids; other threads are local.
  const sessionsRef = useRef(false)
  const [feedbackAdapter] = useState<FeedbackAdapter>(() => ({
    submit: ({ message, type, comment }) => {
      const feedback: AssistantFeedback = {
        type,
        message,
        text: messageText(message),
        sessionId: sessionsRef.current
          ? runtimeRef.current?.threads.mainItem.getState().remoteId
          : undefined,
        ...(comment && { comment }),
      }
      Promise.resolve()
        .then(() => onFeedbackRef.current?.(feedback))
        .catch((error: unknown) => console.error("Feedback failed:", error))
    },
  }))
  const hasFeedback = Boolean(onFeedback)

  const adapters = useMemo(
    () => ({
      dictation: dictationAdapter,
      ...(hasFeedback && { feedback: feedbackAdapter }),
      ...options.adapters,
    }),
    [dictationAdapter, hasFeedback, feedbackAdapter, options.adapters]
  )

  const runtime = useAdkRuntime({
    ...options,
    adapters,
    stream: send,
    sessionAdapter: connection.sessionAdapter,
    load: options.load ?? connection.load,
  })
  useEffect(() => {
    onFeedbackRef.current = onFeedback
    runtimeRef.current = runtime
    sessionsRef.current = Boolean(connection.sessionAdapter)
  })

  return {
    runtime,
    artifacts: connection.artifacts,
    modelSettings,
  }
}

/** A thumbs up or down on one of the agent's replies. */
export type AssistantFeedback = {
  type: "positive" | "negative"
  /** The rated reply. */
  message: ThreadMessage
  /** The reply's text, for logs and review queues. */
  text: string
  /** The reply's ADK session, for direct `adk` connections once it exists. */
  sessionId: string | undefined
  /** A comment, when the UI collects one. */
  comment?: string
}

/** A failed request to the agent server (unreachable, refused, not found) as an ADK error event. */
const requestFailed = (error: unknown): AdkEvent => ({
  id: crypto.randomUUID(),
  errorCode: "REQUEST_FAILED",
  errorMessage: `The assistant couldn't reach the agent: ${
    error instanceof Error ? error.message : String(error)
  }`,
})

const messageText = (message: ThreadMessage) =>
  message.content
    .flatMap((part) => (part.type === "text" ? [part.text] : []))
    .join("\n\n")

const noModels: AssistantModel[] = []

function useModelSettings({
  models,
  defaultModel,
  thinkingLevels,
  defaultThinkingLevel,
}: {
  models: AssistantModel[]
  defaultModel: string | undefined
  thinkingLevels: ThinkingLevel[]
  defaultThinkingLevel: string | undefined
}) {
  // What the person chose; what's selected follows the models as they load
  // or change: the choice while it's one of them, else the default, else
  // the first.
  const [chosenModel, setModel] = useState<string>()
  const [chosenLevel, setThinkingLevel] = useState<string>()
  const listed = (id: string | undefined) =>
    id !== undefined && models.some((option) => option.id === id)
  const model = listed(chosenModel)
    ? chosenModel
    : listed(defaultModel)
      ? defaultModel
      : (models[0]?.id ?? defaultModel)

  // As a string, so a new array with the same levels keeps the same list.
  const offered = models
    .find((option) => option.id === model)
    ?.thinkingLevels?.join(" ")
  const modelLevels = useMemo(() => {
    if (offered === undefined) return thinkingLevels
    const ids = offered.split(" ")
    return thinkingLevels.filter((level) => ids.includes(level.id))
  }, [thinkingLevels, offered])
  const preferred =
    chosenLevel ??
    defaultThinkingLevel ??
    (thinkingLevels.some((level) => level.id === "medium")
      ? "medium"
      : (thinkingLevels[0]?.id ?? ""))
  const thinkingLevel =
    nearestThinkingLevel(modelLevels, thinkingLevels, preferred) ?? preferred

  const [shownBy, setShownBy] = useState(0)
  const show = useCallback(() => {
    setShownBy((count) => count + 1)
    return () => setShownBy((count) => count - 1)
  }, [])

  const settings = useMemo<ModelSettings>(
    () => ({
      models,
      thinkingLevels: modelLevels,
      model,
      thinkingLevel,
      setModel,
      setThinkingLevel,
      show,
    }),
    [models, modelLevels, model, thinkingLevel, show]
  )
  return { settings, shown: shownBy > 0 }
}
